/* ---------- sailors ---------- */
let sq2="",sOpen=new Set(LS.get("sOpen",[]));
function sailorsView(){const TT=teams(),byC={};TT.forEach(t=>byC[t.code]=t);
  const codes=Object.keys(INFO).filter(c=>{try{return squad(c).ppl.length>0}catch(e){return false}});
  const o=c=>byC[c]||{};
  codes.sort((a,b)=>(favs.has(b)?1:0)-(favs.has(a)?1:0)||(o(a).out?1:0)-(o(b).out?1:0)||NM(a).localeCompare(NM(b),lang));
  const all=[];codes.forEach(c=>squad(c).ppl.forEach(p=>all.push({c,p})));
  const qq=sq2.trim().toLowerCase();
  let h=`<div class="tools stools"><input id="q2" type="search" placeholder="${esc(T("sSearch"))}" value="${esc(sq2)}" aria-label="${esc(T("sSearch"))}"></div><p class="scount">${T("sailorsT")(all.length)} · ${T("nations")(codes.length)}</p>`;
  if(qq){const L=all.filter(x=>(x.p.name+" "+x.c+" "+NM(x.c)+" "+(x.p.k||"")+" "+(squad(x.c).n||"")).toLowerCase().includes(qq));
    L.sort((a,b)=>(b.p.img?1:0)-(a.p.img?1:0)||NM(a.c).localeCompare(NM(b.c),lang)||(+a.p.no||99)-(+b.p.no||99));
    const shown=L.slice(0,200);
    return h+(L.length?`<div class="slist">${shown.map(({c,p})=>`<button class="srow" data-sc="${esc(c)}" data-si="${p.i}">${av(p,1)}<span><span class="nmx">${NMH(p.name)}</span><small>${FL(c)}${esc(NM(c))}${p.k?" · "+esc(posL(p)):p.cap?" · "+esc(T("captain")):""}</small></span></button>`).join("")}</div>`:`<p>${T("noTeam")}</p>`)}
  const SF=favSailors();h+=SF.length?`<h3 class="sec">★ ${T("mySailors")}</h3>${sCarousel(SF)}`:`<p class="warn sfh">☆ ${esc(T("sFavHint"))}</p>`;
  /* captains */
  const caps=codes.map(c=>{const pp=squad(c).ppl;const p=pp.find(x=>x.cap)||pp.find(x=>x.k=="Captain");return p?{c,p}:null}).filter(Boolean).sort((a,b)=>(b.p.img?1:0)-(a.p.img?1:0));
  if(caps.length)h+=`<h3 class="sec">${T("sCaps")}</h3><div class="capr">${caps.map(({c,p})=>`<button class="capc" data-sc="${esc(c)}" data-si="${p.i}"><span class="cpa">${p.img?`<img src="${esc(p.img)}" alt="" loading="lazy">`:`<b>${esc(ini(p.name))}</b>`}</span><span class="cpn"><small>${esc(givenN(p.name))}</small>${esc(surname(p.name))}</span><span class="cpf">${FL(c)}${esc(c)}</span></button>`).join("")}</div>`;
  /* squads, by tournament status */
  h+=`<h3 class="sec">${T("sTeams")}</h3><p class="warn">${T("sHint")}</p><div class="sacc">${codes.map(c=>{const sq=squad(c),pp=sq.ppl.filter(p=>!p.extra),t=o(c),pics=pp.filter(p=>p.img).slice(0,4);
    const crew=[...pp].sort((a,b)=>(b.cap?1:0)-(a.cap?1:0)||(/^\d+$/.test(a.no)?+a.no:99)-(/^\d+$/.test(b.no)?+b.no:99));
    return `<details data-sq="${esc(c)}"${sOpen.has(c)?" open":""}${t.out?' class="out"':""}><summary><span class="sqf">${FL(c)}</span><span class="sqn"><b>${esc(NM(c))}${favs.has(c)?' <span class="star">★</span>':""}</b><small>${sq.n?`<span class="tnk">${esc(sq.n)}</span> · `:""}${pp.length} ${esc(T("sailors"))}${t.out?" · "+esc(T("stOut")):""}</small></span><span class="sqs" aria-hidden="true">${pics.map(p=>`<img src="${esc(p.img)}" alt="" loading="lazy">`).join("")}</span><span class="sqc" aria-hidden="true">›</span></summary>
      <div class="sgrid">${crew.map(p=>`<button class="stile" data-sc="${esc(c)}" data-si="${p.i}"><span class="stp">${p.img?`<img src="${esc(p.img)}" alt="" loading="lazy">`:`<b>${esc(ini(p.name))}</b>`}${/^\d+$/.test(p.no)?`<i>${esc(p.no)}</i>`:""}</span><span class="sgn"><small>${esc(givenN(p.name))}</small><b>${esc(surname(p.name))}${sfavs.has(c+"|"+p.name)?' <span class="star">★</span>':""}</b></span><small>${esc(p.k?posL(p):p.cap?T("captain"):"")}</small></button>`).join("")}</div><button class="sqteam" data-t="${esc(c)}">${T("sTeamPage")} ›</button></details>`}).join("")}</div>`;
  return h}
/* ---------- team numbers ---------- */
function teamStats(TM){if(!TM)return"";let races=0,wins=0,pl=[],pts=0;const hist=[];
  TM.path.forEach(s=>{const row=s.g.rows[s.pos-1];if(!row)return;const n=row.r.length;const H=[];
    row.r.forEach((v,i)=>{if(String(v).trim()==="")return;races++;const val=num(v);pts+=val;const m=(i==n-1&&n>1)?2:1,q=val/m;const place=Number.isInteger(q)&&q>=1&&q<=4?5-q:null;if(place){pl.push(place);if(place==1)wins++}H.push({p:place,v:String(v).trim(),n:i+1})});
    if(H.length)hist.push({r:s.r,g:s.g.id,H})});
  if(!races)return"";const avg=pl.length?(pl.reduce((a,b)=>a+b,0)/pl.length).toFixed(1):"–";
  return `<h3>${T("statsT")}</h3><div class="nums"><div><b>${races}</b><small>${T("stRaces")}</small></div><div><b>${wins}</b><small>${T("stWins")}</small></div><div><b>${avg}</b><small>${T("stAvg")}</small></div><div><b>${pts}</b><small>${T("stPts")}</small></div></div>
  <h3>${esc(T("stHist"))}</h3><div class="grp hist2">${hist.map(x=>`<div class="hrd"><div class="hrh">${esc(RNm(x.r))} · ${esc(T("group"))} ${esc(x.g)}</div><div class="hrr">${x.H.map(h=>`<button class="hrc p${h.p||0}" data-race="${esc(x.r.id)}|${esc(x.g)}|${h.n}"><small>${esc(T("race"))} ${h.n}${x.H.length>1&&h.n==x.H.length?" ×2":""}</small><b>${h.p?esc(ord(h.p)):/\*\*/.test(h.v)?"PEN":/\*/.test(h.v)?"OCS":esc(h.v)}</b><em>${esc(String(num(h.v)??h.v))} ${esc(T("rcPts"))}</em></button>`).join("")}</div></div>`).join("")}</div>`}
/* ---------- calendar ---------- */
function calSheet(code){const d=$("#tmd"),base=location.href.split("#")[0].replace(/[^/]*$/,""),file=code?`cal/${code}.ics`:"races.ics",web=base.replace(/^https?:/,"webcal:")+file;
  d.innerHTML=`<div class="th">${code?`<button class="bk">${T("back")}</button>`:""}<div><div class="nick">SSL Gold Cup</div><h2>${T("calT")}</h2></div><div class="thb"><button class="x" aria-label="${T("close")}">✕</button></div></div><div class="tb">
  ${code?`<p class="tst" data-ot="${esc(code)}" role="button">${FL(code)} <b>${esc(NM(code))}</b> ›</p>`:""}<div class="mlist" style="margin-top:12px"><a class="mrow" href="${esc(web)}">${svg('<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/>')}<span><b>${T("calSub")}</b></span></a><a class="mrow" href="https://calendar.google.com/calendar/r?cid=${encodeURIComponent(web)}" target="_blank" rel="noopener">${svg('<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M12 14v4M10 16h4"/>')}<span><b>${T("calG")}</b></span></a><a class="mrow" href="${esc(file)}" download>${svg('<path d="M12 3v12M7 10l5 5 5-5M5 21h14"/>')}<span><b>${T("calDl")}</b></span></a></div><p class="warn">${T("calNote")}</p></div>`;
  d.querySelector(".x").onclick=()=>d.close();const bk=d.querySelector(".bk");if(bk)bk.onclick=()=>d.close();openCode=code||null;show(d)}
/* ---------- share a group as image ---------- */
function loadImg(src){return new Promise(r=>{const i=new Image();i.onload=()=>r(i);i.onerror=()=>r(null);i.src=src})}
async function shareGroup(rid,gid){const r=rnd(rid),g=r&&r.groups.find(x=>x.id==gid);if(!g)return;
  try{await document.fonts.load('600 40px "General Sans"');await document.fonts.load('500 30px "General Sans"')}catch(e){}
  const W=1080,H=470+g.rows.length*150+150,c=document.createElement("canvas");c.width=W;c.height=H;const x=c.getContext("2d");
  const gr=x.createLinearGradient(0,0,W*.6,H);[["#1a4486",0],["#0a5590",.3],["#095d88",.52],["#0b6166",.76],["#255c2c",1]].forEach(([col,t])=>gr.addColorStop(t,col));x.fillStyle=gr;x.fillRect(0,0,W,H);
  const F='"General Sans",system-ui,sans-serif';const lk=await loadImg("brand/lockup.webp");if(lk)x.drawImage(lk,80,70,560,560*lk.height/lk.width);
  const ssl=await loadImg("brand/ssl.png");if(ssl)x.drawImage(ssl,W-80-120,90,120,120*ssl.height/ssl.width);
  x.fillStyle="#fff";x.font=`600 64px ${F}`;x.fillText(RNm(r),80,330);x.font=`500 40px ${F}`;x.fillStyle="rgba(255,255,255,.85)";x.fillText((r.groups.length>1?T("group")+" "+g.id+" · ":"")+range(r),80,390);
  const n=g.rows[0].r.length,y0=470,rh=150,gs=gState(g,r);
  {const cx=k=>W-60-130-72*(n-k)+36;x.font=`500 28px ${F}`;x.fillStyle="rgba(255,255,255,.7)";x.textAlign="center";for(let k=0;k<n;k++)x.fillText(n>1?"R"+(k+1):"",cx(k),y0-18);x.fillText(T("pts"),W-60-62,y0-18);x.textAlign="left"}
  for(let i=0;i<g.rows.length;i++){const row=g.rows[i],y=y0+i*rh,o=outcome(r.id,i+1,gs=="done"),w=o&&o[0]=="w";
    x.fillStyle=w?"rgba(255,255,255,.2)":"rgba(255,255,255,.08)";x.beginPath();x.roundRect?x.roundRect(60,y,W-120,rh-20,24):x.rect(60,y,W-120,rh-20);x.fill();
    x.fillStyle="#fff";x.font=`600 46px ${F}`;x.fillText(String(i+1),100,y+82);
    const iso2=iso(row.team);if(iso2){const fi=await loadImg(`img/fl/${iso2.toLowerCase()}.webp`);if(fi)x.drawImage(fi,160,y+38,72,54)}
    const cx=k=>W-60-130-72*(n-k)+36,maxW=cx(0)-36-256-16;let fs=46,nm=isTeam(row.team)?NM(row.team):ph(row.team)||row.team;x.font=`600 ${fs}px ${F}`;while(x.measureText(nm).width>maxW&&fs>30){fs-=2;x.font=`600 ${fs}px ${F}`}while(x.measureText(nm).width>maxW&&nm.length>4)nm=nm.slice(0,-2)+"…";x.fillText(nm,256,y+82);
    x.font=`500 38px ${F}`;x.fillStyle="rgba(255,255,255,.85)";row.r.forEach((v,k)=>{x.textAlign="center";x.fillText(String(v||"–"),cx(k),y+80)});
    x.font=`600 52px ${F}`;x.fillStyle="#ffd21f";const tot=String(row.total||"").trim()||String(row.r.reduce((s,v)=>s+num(v),0));x.textAlign="center";x.fillText(tot,W-60-62,y+82);x.textAlign="left"}
  x.font=`500 32px ${F}`;x.fillStyle="rgba(255,255,255,.8)";x.fillText(location.host+location.pathname.replace(/index\.html$/,""),80,H-70);
  const blob=await new Promise(res=>c.toBlob(res,"image/png"));if(!blob)return;const fn=`gold-cup-${rid}-${gid}.png`;
  try{const file=new File([blob],fn,{type:"image/png"});if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:"SSL Gold Cup"});return}}catch(e){if(e&&e.name=="AbortError")return}
  const u=URL.createObjectURL(blob),d=$("#tmd");d.innerHTML=`<div class="th"><div><div class="nick">SSL Gold Cup</div><h2>${T("imgDone")}</h2></div><div class="thb"><button class="x" aria-label="${T("close")}">✕</button></div></div><div class="tb"><img src="${u}" alt="" style="width:100%;border-radius:14px"><div class="tact"><a class="ibtn" href="${u}" download="${fn}" style="text-align:center;text-decoration:none">⬇ PNG</a></div></div>`;
  d.querySelector(".x").onclick=()=>d.close();openCode=null;show(d)}

