let PP=LS.get("pp",{});const ppSave=()=>LS.set("pp",PP);
async function pushEnsure(){if(!pushReady()){pushHelp();return null}let perm=Notification.permission;
  if(perm!=="granted"){if(perm==="denied"){toast(T("pDenied"));return null}try{perm=await Notification.requestPermission()}catch(e){}if(perm!=="granted"){toast(T(perm==="denied"?"pDenied":"pErr"));return null}}
  try{const O=await loadOS();await O.User.PushSubscription.optIn();O.User.addTags({l:lang});if(SPOIL)O.User.addTag("spoiler","1");LS.set("pon",1);return O}catch(e){console.warn("push",e);toast(T("pErr"));return null}}
const pushOn=()=>!!CFG.push&&LS.get("pon",pSet.size?1:0)==1&&"Notification" in window&&Notification.permission==="granted";
async function pushPref(k,v){const O=await pushEnsure();if(!O)return;try{if(v===false||v==null||v==="off"){O.User.removeTag(k);delete PP[k]}else{O.User.addTag(k,String(v));PP[k]=v}ppSave();toast(T("pOnT"))}catch(e){toast(T("pErr"))}}
function quietUtc(start){const off=new Date().getTimezoneOffset();return String(((Math.round((start*60+off)/60))%24+24)%24)}
