const CONT={en:["Africa","Asia","Europe","Oceania","Pan-America"],de:["Afrika","Asien","Europa","Ozeanien","Panamerika"],fr:["Afrique","Asie","Europe","Océanie","Amériques"],es:["África","Asia","Europa","Oceanía","Panamérica"],pt:["África","Ásia","Europa","Oceania","Pan-América"],zh:["非洲","亚洲","欧洲","大洋洲","泛美"],ar:["أفريقيا","آسيا","أوروبا","أوقيانوسيا","الأمريكتان"],hi:["अफ़्रीका","एशिया","यूरोप","ओशिनिया","पैन-अमेरिका"],bn:["আফ্রিকা","এশিয়া","ইউরোপ","ওশেনিয়া","প্যান-আমেরিকা"],ur:["افریقہ","ایشیا","یورپ","اوشیانا","پین امریکا"],id:["Afrika","Asia","Eropa","Oseania","Pan-Amerika"],ms:["Afrika","Asia","Eropah","Oceania","Pan-Amerika"],ja:["アフリカ","アジア","ヨーロッパ","オセアニア","汎アメリカ"],th:["แอฟริกา","เอเชีย","ยุโรป","โอเชียเนีย","แพนอเมริกา"],hu:["Afrika","Ázsia","Európa","Óceánia","Pánamerika"],cs:["Afrika","Asie","Evropa","Oceánie","Panamerika"],uk:["Африка","Азія","Європа","Океанія","Панамерика"],pl:["Afryka","Azja","Europa","Oceania","Panameryka"]};
const CSLUG={africa:0,asia:1,europe:2,oceania:3,"pan-america":4};
const RK={idx:null,wk:{},p:null};let RKST={c:"",q:"",w:"",gc:false,open:new Set()};
function rkIdx(){if(RK.idx)return Promise.resolve(RK.idx);if(RK.p)return RK.p;RK.p=fetch("rank/index.json").then(r=>r.ok?r.json():null).then(j=>{RK.idx=j&&j.date?j:null;RK.p=null;return RK.idx}).catch(()=>{RK.p=null;return null});return RK.p}
function rkWeek(d){if(RK.wk[d])return Promise.resolve(RK.wk[d]);return fetch(`rank/${d}.json`).then(r=>r.ok?r.json():null).then(j=>{if(j)RK.wk[d]=j;return j}).catch(()=>null)}
function rkCur(){return rkIdx().then(i=>i?rkWeek(i.date):null)}
const rkCode=c=>{for(const k in INFO)if(k==c)return k;return null};
const rkName=r=>{const gc=INFO[r[3]]?r[3]:null;if(gc)return NM(gc);try{const iso2=(r[4]||"").split("-")[0].toUpperCase();if(iso2.length==2){const n=new Intl.DisplayNames([LOC()],{type:"region"}).of(iso2);if(n&&n!=iso2)return n}}catch(e){}return String(r[5]||r[3]).toLowerCase().replace(/(^|[\s-])\S/g,m=>m.toUpperCase())};
const rkFlag=iso=>iso?`<img class="flg" src="img/fl/${esc(iso)}.webp" onerror="this.onerror=null;this.src='img/fl/${esc(iso)}.svg'" alt="" width="22" height="16" loading="lazy">`:"";
function rkSailor(code,first,last){if(!INFO[code])return null;try{const sq=squad(code),k=(first+" "+last).normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase(),t=tok(first+" "+last);return sq.ppl.find(p=>p.name.normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase()==k)||sq.ppl.find(p=>{const q=tok(p.name);return t.length>1&&t.every(w=>q.includes(w))})||null}catch(e){return null}}
function rkPeople(code,L){return `<div class="rkpl">${L.map(([pos,pts,f,l,sl,img])=>{const p=rkSailor(code,f,l);const ph=img?`<img src="https://platform.worldofsailors.com/storage/${esc(img)}" alt="" loading="lazy" onerror="this.remove()">`:"";return `<${p?`button data-sc="${esc(code)}" data-si="${p.i}"`:"div"} class="rkp"><span class="rkav">${ph}<b>${esc(ini(f+" "+l))}</b></span><span class="rkpn"><small>${esc(f)}</small><b>${esc(l)}</b></span><span class="rkpr"><small>${esc(T("rkInd"))}</small><b>#${pos}</b></span>${p?`<i>›</i>`:""}</${p?"button":"div"}>`}).join("")}</div>`}
function rkTrend(r){const p=r[0],b=r[2];if(!b||b==p)return `<span class="rktr eq" aria-hidden="true">•</span>`;return b>p?`<span class="rktr up" title="${esc(T("rkWas")(b))}">▲${b-p}</span>`:`<span class="rktr dn" title="${esc(T("rkWas")(b))}">▼${p-b}</span>`}
function pRank(){const d=$("#pg");openCode=null;
  d.innerHTML=`<div class="th"><div><div class="nick">Star Sailors League</div><h2>${esc(T("rkT"))}</h2></div></div><div class="tb rk"><p class="warn">${esc(T("rkLoad"))}</p></div>`;pgShow(d);
  rkIdx().then(ix=>{if(!ix){d.querySelector(".tb").innerHTML=`<p class="warn">${esc(T("rkFail"))}</p>`;return}const w=RKST.w&&ix.weeks.includes(RKST.w)?RKST.w:ix.date;return rkWeek(w).then(W=>{if(!PGS||PGS.t!="rank")return;if(!W){d.querySelector(".tb").innerHTML=`<p class="warn">${esc(T("rkFail"))}</p>`;return}rkPaint(d,ix,W)})})}
function rkPaint(d,ix,W){const tb=d.querySelector(".tb"),y=d.scrollTop,cn=CONT[lang]||CONT.en,fmt=s=>{try{return new Date(s+"T12:00:00").toLocaleDateString(LOC(),{day:"numeric",month:"short",year:"numeric"})}catch(e){return s}};
  const cid=RKST.c?(ix.continents.find(c=>c.slug==RKST.c)||{}).id:null,q=RKST.q.trim().normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase();
  let L=W.n.filter(r=>(!cid||r[6]==cid)&&(!RKST.gc||INFO[r[3]])&&(!q||[rkName(r),r[5],r[3]].some(s=>String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase().includes(q))));
  let h=`<div class="rkhead"><div><small>${esc(T("rkAsOf"))}</small><b>${esc(fmt(W.date))}</b></div><div><small>${esc(T("rkGlob"))}</small><b>${esc(T("rkNat")(W.n.length))}</b></div></div>`;
  h+=`<div class="rkchips" role="group"><button data-rkc="" class="${RKST.c?"":"on"}">${esc(T("rkAll"))}</button>${ix.continents.filter(c=>c.slug in CSLUG).sort((a,b)=>CSLUG[a.slug]-CSLUG[b.slug]).map(c=>`<button data-rkc="${esc(c.slug)}" class="${RKST.c==c.slug?"on":""}">${esc(cn[CSLUG[c.slug]])}</button>`).join("")}<button data-rkg="1" class="gc${RKST.gc?" on":""}">★ ${esc(T("rkGC"))}</button></div>`;
  h+=`<div class="rkf"><label class="rks">${svg('<circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/>')}<input id="rkq" type="search" placeholder="${esc(T("rkSearch"))}" value="${esc(RKST.q)}" autocomplete="off"></label><label class="rkw"><small>${esc(T("rkHist"))}</small><select id="rkw">${ix.weeks.map((w,i)=>`<option value="${w}"${w==W.date?" selected":""}>${i==0?esc(T("rkCur"))+" · ":""}${esc(fmt(w))}</option>`).join("")}</select></label></div>`;
  h+=`<div class="rktb"><div class="rkr rkh"><span>${esc(T("rkNo"))}</span><span>${esc(T("rkGlob"))}</span><span></span><span>${esc(T("rkName"))}</span></div>`;
  h+=L.length?L.map((r,i)=>{const op=RKST.open.has(r[3]),gc=INFO[r[3]];return `<div class="rkrow${op?" op":""}${gc?" isgc":""}" data-rk="${esc(r[3])}"><button class="rkr" aria-expanded="${op}"><span class="rkn">${String(i+1).padStart(2,"0")}</span><span class="rkg${r[0]<=3?" rk3":""}">${String(r[0]).padStart(2,"0")}</span>${rkTrend(r)}<span class="rknm">${rkFlag(r[4])}<b>${esc(rkName(r))}</b>${gc?`<em>GC</em>`:""}</span><i class="rkch">›</i></button>${op?`<div class="rkd">${r[2]&&r[2]!=r[0]?`<p class="warn">${esc(T("rkPrev")("#"+r[2]))}</p>`:""}${r[7].length?`<h4>${esc(T("rkSk"))}</h4>${rkPeople(r[3],r[7])}`:""}${r[8].length?`<h4>${esc(T("rkCr"))}</h4>${rkPeople(r[3],r[8])}`:""}<div class="rkfoot"><span>${esc(T("rkPts"))}: <b>${r[1]}</b></span>${gc?`<button data-ot="${esc(r[3])}">${esc(T("rkTeam"))} ›</button>`:""}</div></div>`:""}</div>`}).join(""):`<p class="pad warn">${esc(T("rkNone"))}</p>`;
  h+=`</div><p class="warn">${esc(T("rkTap"))} ${esc(T("rkSrc"))}</p>`;
  tb.innerHTML=h;d.scrollTop=y;
  tb.querySelectorAll("[data-rkc]").forEach(b=>b.onclick=()=>{RKST.c=b.dataset.rkc;rkPaint(d,ix,W)});
  tb.querySelector("[data-rkg]").onclick=()=>{RKST.gc=!RKST.gc;rkPaint(d,ix,W)};
  const qi=tb.querySelector("#rkq");qi.oninput=()=>{RKST.q=qi.value;const p=qi.selectionStart;rkPaint(d,ix,W);const n=d.querySelector("#rkq");n.focus();try{n.setSelectionRange(p,p)}catch(e){}};
  tb.querySelector("#rkw").onchange=e=>{RKST.w=e.target.value;tb.style.opacity=".5";rkWeek(RKST.w).then(N=>{tb.style.opacity="";if(N)rkPaint(d,ix,N)})};
  tb.querySelectorAll(".rkrow>.rkr").forEach(b=>b.onclick=()=>{const c=b.parentNode.dataset.rk;RKST.open.has(c)?RKST.open.delete(c):RKST.open.add(c);rkPaint(d,ix,W)})}
