/* ---------- detailed sailing weather for a race (Open-Meteo forecast + marine) ---------- */
const WXC={};
async function wxDay(d){if(WXC[d])return WXC[d];const base=`timezone=America%2FSao_Paulo&start_date=${d}&end_date=${d}`;
  const [a,m]=await Promise.all([fetch(`https://api.open-meteo.com/v1/forecast?latitude=${VENUE.lat}&longitude=${VENUE.lng}&hourly=wind_speed_10m,wind_gusts_10m,wind_direction_10m,temperature_2m,precipitation_probability,cloud_cover,pressure_msl&daily=sunrise,sunset&wind_speed_unit=kn&${base}`).then(r=>r.ok?r.json():null).catch(()=>null),
    fetch(`https://marine-api.open-meteo.com/v1/marine?latitude=-22.94&longitude=-43.14&hourly=wave_height,wave_period,wave_direction,sea_surface_temperature,sea_level_height_msl,ocean_current_velocity,ocean_current_direction&${base}`).then(r=>r.ok?r.json():null).catch(()=>null)]);
  if(!a||!a.hourly)return null;return WXC[d]={a,m}}
const CMP={de:"N NNO NO ONO O OSO SO SSO S SSW SW WSW W WNW NW NNW",fr:"N NNE NE ENE E ESE SE SSE S SSO SO OSO O ONO NO NNO",es:"N NNE NE ENE E ESE SE SSE S SSO SO OSO O ONO NO NNO",pt:"N NNE NE ENE L ESE SE SSE S SSO SO OSO O ONO NO NNO"};
const cmp16=deg=>(CMP[lang]||"N NNE NE ENE E ESE SE SSE S SSW SW WSW W WNW NW NNW").split(" ")[Math.round(((deg%360)+360)%360/22.5)%16];
const arr=(deg,go)=>`<i class="wa" style="transform:rotate(${(deg+(go?180:0))%360}deg)">↓</i>`;
async function openWx(x){const d=sheetWrap(`${T("wxH")} · Marina da Glória`,`${wday(x.d)} · ${x.t} ${T("rioT")}`,`<p class="warn">${esc(T("wxLoad"))}</p>`);const tb=d.querySelector(".tb");gcEvent("weather");
  const W=await wxDay(x.d);if(!d.open)return;if(!W){tb.innerHTML=`<p>${esc(T("wxFail"))}</p>${wxLinks()}`;return}
  const H=wxConv(W.a.hourly),M=W.m&&W.m.hourly,ix=t=>H.time.indexOf(`${x.d}T${t}`),st=ix(x.t.slice(0,2)+":00");
  const r1=n=>Math.round(n),f1=n=>(Math.round(n*10)/10).toLocaleString(LOC());
  const hrs=[];for(let h=10;h<=18;h++){const i=ix(String(h).padStart(2,"0")+":00");if(i>=0)hrs.push(i)}
  const mx=Math.max(1,...hrs.map(i=>H.wind_gusts_10m[i]||0));
  const st0=st;const paint=st=>{let h="";const hh=H.time[st]?H.time[st].slice(11,16):x.t.slice(0,2)+":00";
  if(st>=0){const w=H.wind_speed_10m[st],g=H.wind_gusts_10m[st],dir=H.wind_direction_10m[st],p0=H.pressure_msl[st],p3=H.pressure_msl[Math.max(0,st-3)];
    const bft=[1,4,7,11,17,22,28,34,41,48,56,64].filter(v=>w>=v).length,cond=T("fcCond")[w<8?0:w<15?1:w<21?2:3];
    const n1=Math.min(H.time.length-1,st+1),dw=H.wind_speed_10m[n1]-w,dd=((H.wind_direction_10m[n1]-dir+540)%360)-180;
    const tr=[Math.abs(dw)>=2?T("fcTr")[dw>0?"up":"down"]:T("fcTr").steady,Math.abs(dd)>=10?T("fcTr")[dd>0?"veer":"back"]+` (${dd>0?"+":""}${r1(dd)}°)`:""].filter(Boolean).join(" · ");
    h+=`<div class="fcbar"><span class="fcc">${esc(cond)}</span><span>${esc(T("fcBft"))} ${bft}</span><span>${esc(T("fcNext"))}: ${esc(tr)}</span></div>`;
    h+=`<div class="wxhero"><div class="wxtop">${rose(dir,w)}<div class="wxdir"><small>${esc(WXF[lang]||WXF.en)}</small><b>${esc(cmp16(dir))}</b><em>${r1(dir)}°</em><div class="wxgust"><small>${esc(T("wxGust"))}</small><b>${r1(g)}</b><span>${uW()}</span></div></div></div><div class="wxtiles"><div>${wi("t")}<b>${f1(H.temperature_2m[st])} ${uT()}</b></div><div>${wi("r")}<b>${r1(H.precipitation_probability[st]??0)} %</b></div><div>${wi("c")}<b>${r1(H.cloud_cover[st])} %</b></div><div>${wi("p")}<b>${r1(p0)}<i> hPa ${p0-p3>1?"↗":p0-p3<-1?"↘":"→"}</i></b></div></div></div><p class="warn">${esc(st==st0?T("wxAtStart"):T("wxAtT")(hh))} · ${esc(T("wxTap"))}</p>`}
  h+=wxChart(H,hrs,st,mx);
  h+=`<h3>${esc(T("wxHours"))}</h3><div class="grp wxt"><div class="wxr wxhd"><span>${esc(T("wxTime"))}</span><span>${esc(T("wxWind").replace("kn",uW()))}</span><span></span><span>${esc(T("wxDir"))}</span><span>${uT()}</span><span>${wi("r")}</span></div>${hrs.map(i=>{const w=H.wind_speed_10m[i],g=H.wind_gusts_10m[i],dir=H.wind_direction_10m[i];return `<div class="wxr${i==st?" now":""}${i==st0?" st":""}" data-hi="${i}" role="button" tabindex="0"><span>${H.time[i].slice(11,16)}</span><span><b>${r1(w)}</b>–${r1(g)}</span><span class="wbar"><i style="width:${w/mx*100}%"></i><i class="gu" style="width:${(g-w)/mx*100}%"></i></span><span>${arr(dir)}${esc(cmp16(dir))}</span><span>${r1(H.temperature_2m[i])}</span><span>${r1(H.precipitation_probability[i]??0)}%</span></div>`}).join("")}</div><p class="warn">${esc(T("wxKn"))}</p>`;
  if(M&&M.time){const mi=t=>M.time.indexOf(`${x.d}T${t}`),ms=mi(hh);const v=(k,i)=>M[k]&&M[k][i]!=null?M[k][i]:null;
    if(ms>=0){const sl=M.sea_level_height_msl||[],up=v("sea_level_height_msl",ms+1)!=null&&v("sea_level_height_msl",ms)!=null?v("sea_level_height_msl",ms+1)-v("sea_level_height_msl",ms):0;
      const ext=[];for(let i=1;i<sl.length-1;i++){if(sl[i]==null||sl[i-1]==null||sl[i+1]==null)continue;if(sl[i]>=sl[i-1]&&sl[i]>sl[i+1])ext.push(`${T("wxHigh")} ${M.time[i].slice(11,16)}`);if(sl[i]<=sl[i-1]&&sl[i]<sl[i+1])ext.push(`${T("wxLow")} ${M.time[i].slice(11,16)}`)}
      const cur=v("ocean_current_velocity",ms),cd=v("ocean_current_direction",ms);
      h+=`<h3>${esc(T("wxSea"))}</h3><div class="grp wxs">${v("sea_surface_temperature",ms)!=null?`<div><small>${esc(T("wxWater"))}</small><b>${f1(tvc(v("sea_surface_temperature",ms)))} ${uT()}</b></div>`:""}${v("sea_level_height_msl",ms)!=null?`<div><small>${esc(T("wxTide"))}</small><b>${up>0.01?"↗ "+esc(T("wxRise")):up<-0.01?"↘ "+esc(T("wxFall")):"→"}</b><em>${esc(ext.join(" · "))}</em></div>`:""}${cur!=null?`<div><small>${esc(T("wxCur"))}</small><b>${f1(wvc(cur/1.852))} ${uW()} ${cd!=null?arr(cd,false)+esc(cmp16(cd)):""}</b><em>${esc(T("wxCurN"))}</em></div>`:""}${v("wave_height",ms)!=null?`<div><small>${esc(T("wxWave"))}</small><b>${f1(v("wave_height",ms))} m · ${r1(v("wave_period",ms)||0)} s</b><em>${esc(T("wxWaveN"))}</em></div>`:""}</div>`}}
  const dl=W.a.daily;if(dl&&dl.sunrise)h+=`<p class="warn">☀ ${esc(T("wxSun"))}: ${String(dl.sunrise[0]).slice(11,16)} – ${String(dl.sunset[0]).slice(11,16)}</p>`;
  h+=`<p class="warn">${esc(T("wxSrc2"))}</p>${wxLinks()}`;const y=d.scrollTop;tb.innerHTML=h;d.scrollTop=y;tb.querySelectorAll("[data-hi]").forEach(el=>{el.onclick=()=>paint(+el.dataset.hi);el.onkeydown=e=>{if(e.key=="Enter")paint(+el.dataset.hi)}})};paint(st0)}
const WI={t:'<path d="M10 14V5a2 2 0 014 0v9a4 4 0 11-4 0z"/>',r:'<path d="M7 15a4 4 0 01-.5-8A5.5 5.5 0 0117 6a3.5 3.5 0 01.5 7"/><path d="M9 17l-1 3M13 17l-1 3M17 16l-1 3"/>',c:'<path d="M7 18a4 4 0 01-.5-8A5.5 5.5 0 0117 9a3.5 3.5 0 01.5 7H7z"/>',p:'<circle cx="12" cy="13" r="8"/><path d="M12 13l4-3"/>'};
const wi=k=>svg(WI[k],"wic");
const ALSO={en:"also",de:"auch",fr:"aussi",es:"también",pt:"também",zh:"也任",ar:"أيضًا",hi:"यह भी",bn:"এছাড়াও",ur:"یہ بھی",id:"juga",ms:"juga",ja:"兼",th:"หรือ",hu:"is:",cs:"také",uk:"також",pl:"także"};for(const l in ALSO)if(S[l])S[l].alsoP=ALSO[l];
const WXF={en:"Wind from",de:"Wind aus",fr:"Vent du",es:"Viento del",pt:"Vento de",zh:"风向（来自）",ar:"الرياح من",hi:"हवा की दिशा (से)",bn:"বাতাস আসছে",ur:"ہوا کا رخ (سے)",id:"Angin dari",ms:"Angin dari",ja:"風向（から）",th:"ลมมาจาก",hu:"Szél iránya",cs:"Vítr od",uk:"Вітер з",pl:"Wiatr z"};
function rose(dir,w){const P=(r,a)=>[50+r*Math.sin(a*Math.PI/180),50-r*Math.cos(a*Math.PI/180)].map(v=>v.toFixed(1));
  const near=a=>Math.abs(((dir-a+540)%360)-180)<25;
  const pts=["N","E","S","W"].map((c,i)=>{const[x,y]=P(33,i*90);return `<text x="${x}" y="${(+y+3.2).toFixed(1)}" text-anchor="middle" font-size="9" fill="currentColor" opacity="${near(i*90)?0.12:0.6}">${c}</text>`}).join("");
  const tk=Array.from({length:36},(_,i)=>{const a=i*10,[x1,y1]=P(i%9?44:41.5,a),[x2,y2]=P(47,a);return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="currentColor" stroke-width="${i%9?0.8:1.4}" opacity="${i%9?0.25:0.55}"/>`}).join("");
  return `<svg class="rose" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="47" fill="none" stroke="currentColor" opacity=".18"/>${tk}${pts}<g transform="rotate(${Math.round(dir)} 50 50)"><path d="M50 27 L41.5 4.5 Q50 1 58.5 4.5 Z" fill="#f5b800"/></g><text x="50" y="57" text-anchor="middle" font-size="25" font-weight="700" fill="currentColor">${Math.round(w)}</text><text x="50" y="68" text-anchor="middle" font-size="8.5" fill="currentColor" opacity=".6">${uW()}</text></svg>`}
